/* Helpers */
function getProduct(id){ return PRODUCTS.find(p => p.id === id); }
function productsByCat(cat){ return PRODUCTS.filter(p => p.cat === cat); }
function gradOf(p){ return (window.GRADIENTS || GRADIENTS)[p.grad] || GRADIENTS.candy; }
window.PRODUCTS = PRODUCTS; window.GRADIENTS = GRADIENTS;
window.getProduct = getProduct; window.productsByCat = productsByCat; window.gradOf = gradOf;
